package in.tallybridge.app;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.concurrent.*;

/** Daily operations center. Uses only authenticated bridge APIs and saved/read-only Tally data. */
public final class WorkActivity extends Activity {
 private final ExecutorService work=Executors.newSingleThreadExecutor();
 private final Handler main=new Handler(Looper.getMainLooper());
 private CryptoStore store; private BridgeApi api; private String company=""; private boolean dark=false,destroyed=false;
 private LinearLayout root,body; private ProgressBar progress; private int NAVY,TEAL,MUTED,BG,SURFACE,BORDER,TINT,AMBER,RED,INK;
 private final NumberFormat money=NumberFormat.getCurrencyInstance(new Locale("en","IN"));

 @Override public void onCreate(Bundle b){applyTheme();super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);styleWindow();try{store=new CryptoStore(this);api=new BridgeApi(store);company=store.get("company");}catch(Exception e){fatal(e);return;}if(store.get("base").isEmpty()||store.get("device").isEmpty()){finish();startActivity(new Intent(this,MainActivity.class));return;}showToday();}
 @Override protected void onDestroy(){destroyed=true;work.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
 @Override protected void onStop(){super.onStop();if(!isChangingConfigurations())finish();}
 private String appearance(){return getSharedPreferences("appearance",MODE_PRIVATE).getString("mode","System");}
 private void applyTheme(){String m=appearance();dark=m.equals("Dark")||(m.equals("System")&&(getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES);setTheme(dark?R.style.AppThemeDark:R.style.AppThemeLight);NAVY=dark?0xffe6edf3:0xff102d44;TEAL=dark?0xff7bd8bd:0xff176b5b;MUTED=dark?0xffa7b8c5:0xff596c79;BG=dark?0xff101820:0xfff5f7fa;SURFACE=dark?0xff1b2732:Color.WHITE;BORDER=dark?0xff344552:0xffe4eaef;TINT=dark?0xff203f3a:0xffe5f2ee;AMBER=dark?0xffffc857:0xff8a5a00;RED=dark?0xffff9c9c:0xffa12626;INK=dark?0xff102d26:Color.WHITE;}
 private void styleWindow(){getWindow().getDecorView().setSystemUiVisibility(dark?0:(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR));getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(SURFACE);}
 private int dp(float x){return Math.round(x*getResources().getDisplayMetrics().density);}
 private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private TextView text(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setLineSpacing(dp(2),1f);v.setPadding(0,dp(3),0,dp(3));return v;}
 private GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));d.setStroke(dp(1),BORDER);return d;}
 private Button button(String s,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(TEAL);b.setTextSize(14);b.setBackground(shape(SURFACE,12));b.setMinHeight(dp(48));b.setOnClickListener(l);return b;}
 private Button primary(String s,View.OnClickListener l){Button b=button(s,l);b.setTextColor(INK);b.setBackground(shape(TEAL,12));return b;}
 private LinearLayout.LayoutParams full(int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(top),0,0);return p;}
 private void gap(LinearLayout l,int h){l.addView(new View(this),new LinearLayout.LayoutParams(1,dp(h)));}
 private void fatal(Exception e){TextView v=text("Today could not start.\n"+(e.getMessage()==null?"Unknown error":e.getMessage()),16,NAVY);v.setPadding(dp(24),dp(60),dp(24),dp(24));v.setBackgroundColor(BG);setContentView(v);}
 private String amount(double v){return money.format(v);}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}

 private void frame(String title,String subtitle){root=col();root.setBackgroundColor(BG);root.setPadding(dp(18),dp(14),dp(18),0);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);LinearLayout titles=col();TextView t=text(title,25,NAVY);t.setTypeface(null,Typeface.BOLD);titles.addView(t);titles.addView(text(subtitle,12,MUTED));top.addView(titles,new LinearLayout.LayoutParams(0,-2,1));Button back=button("Back",v->finish());top.addView(back,new LinearLayout.LayoutParams(dp(80),-2));root.addView(top);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);progress.setVisibility(View.GONE);progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(TEAL));root.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));LinearLayout tabs=new LinearLayout(this);String[] names={"Today","Search","Customer","Follow-ups","System"};View.OnClickListener[] clicks={v->showToday(),v->showSearch(),v->customerPicker(),v->showFollowUps(),v->showSystem()};for(int i=0;i<names.length;i++){Button b=button(names[i],clicks[i]);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(2),dp(8),dp(2),dp(4));tabs.addView(b,lp);}HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);hs.addView(tabs,new HorizontalScrollView.LayoutParams(dp(620),-2));root.addView(hs);ScrollView sv=new ScrollView(this);body=col();body.setPadding(dp(2),dp(10),dp(2),dp(30));sv.addView(body);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 private void busy(boolean yes){if(progress!=null)progress.setVisibility(yes?View.VISIBLE:View.GONE);}
 private void heading(String t,String d){TextView a=text(t,19,NAVY);a.setTypeface(null,Typeface.BOLD);body.addView(a,full(14));if(d!=null&&!d.isEmpty())body.addView(text(d,12,MUTED));}
 private void card(String title,String detail,String value,View.OnClickListener click){LinearLayout c=col();c.setPadding(dp(15),dp(13),dp(15),dp(13));c.setBackground(shape(SURFACE,14));TextView t=text(title,15,NAVY);t.setTypeface(null,Typeface.BOLD);c.addView(t);if(detail!=null&&!detail.isEmpty())c.addView(text(detail,12,MUTED));if(value!=null&&!value.isEmpty()){TextView v=text(value,19,TEAL);v.setTypeface(null,Typeface.BOLD);c.addView(v,full(4));}if(click!=null){c.setOnClickListener(click);c.setFocusable(true);}body.addView(c,full(8));}
 private String path(String ep,String...p){return BridgeApi.path(ep,company,p);}
 private void get(String title,String url,java.util.function.Consumer<JSONObject> render){busy(true);work.execute(()->{try{JSONObject x=api.get(url);main.post(()->{if(destroyed)return;busy(false);render.accept(x);});}catch(Exception e){main.post(()->{if(destroyed)return;busy(false);card("Could not load "+title,e.getMessage(),"",v->get(title,url,render));});}});}
 private void post(String url,JSONObject payload,Runnable done){busy(true);work.execute(()->{try{api.call(url,"POST",payload.toString());main.post(()->{if(destroyed)return;busy(false);done.run();});}catch(Exception e){main.post(()->{if(destroyed)return;busy(false);toast(e.getMessage());});}});}

 private void showToday(){frame("Today","Daily work • "+company);get("Today",path("workspace"),this::renderToday);}
 private void renderToday(JSONObject x){
  body.removeAllViews();heading(x.optBoolean("tallyOnline")?"Business ready":"Saved mode",x.optBoolean("tallyOnline")?"Tally is connected. Figures below use the latest synchronized data.":"Tally is unavailable. Last-known-good figures remain visible.");
  LinearLayout quick=new LinearLayout(this);Button q=primary("+ Quick order",v->{Intent i=new Intent(this,OrdersActivity.class);i.setAction(OrdersActivity.ACTION_QUICK);startActivity(i);});Button o=button("Orders",v->startActivity(new Intent(this,OrdersActivity.class)));quick.addView(q,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(0,-2,1);op.setMargins(dp(8),0,0,0);quick.addView(o,op);body.addView(quick,full(12));
  card("Pending orders",x.optInt("oldPendingOrders")+" pending for 2+ days",String.valueOf(x.optInt("pendingOrders")),v->startActivity(new Intent(this,OrdersActivity.class)));
  card("Dispatched today","Orders marked dispatched today",String.valueOf(x.optInt("dispatchedToday")),v->startActivity(new Intent(this,OrdersActivity.class)));
  card("Sales today",x.optInt("salesCount")+" posted invoices",amount(x.optDouble("salesToday")),null);
  card("Receivable","Saved outstanding balance",amount(x.optDouble("receivable")),null);card("Payable","Saved outstanding balance",amount(x.optDouble("payable")),null);
  card("Payment follow-ups",x.optInt("followUpsDue")+" due today • "+x.optInt("followUpsOverdue")+" overdue",String.valueOf(x.optInt("followUpsDue")+x.optInt("followUpsOverdue")),v->showFollowUps());
  JSONArray alerts=x.optJSONArray("alerts");heading("Needs attention",alerts==null||alerts.length()==0?"Nothing urgent detected.":alerts.length()+" useful alert(s)");if(alerts!=null)for(int i=0;i<alerts.length();i++){JSONObject a=alerts.optJSONObject(i);if(a==null)continue;String sev=a.optString("severity");int c="critical".equals(sev)?RED:"warning".equals(sev)?AMBER:TEAL;LinearLayout box=col();box.setPadding(dp(14),dp(12),dp(14),dp(12));box.setBackground(shape(SURFACE,13));TextView t=text(a.optString("title"),14,c);t.setTypeface(null,Typeface.BOLD);box.addView(t);box.addView(text(a.optString("detail"),12,MUTED));String action=a.optString("action");box.setOnClickListener(v->{if("orders".equals(action))startActivity(new Intent(this,OrdersActivity.class));else if("followups".equals(action))showFollowUps();else showSystem();});body.addView(box,full(7));}
 }

 private void showSearch(){frame("Search","Invoices • parties • orders • LR/RR • GSTIN • follow-ups");EditText q=new EditText(this);q.setHint("Search anything saved in TallyBridge");q.setTextColor(NAVY);q.setHintTextColor(MUTED);q.setTextSize(16);q.setSingleLine(true);q.setPadding(dp(14),dp(12),dp(14),dp(12));q.setBackground(shape(SURFACE,12));body.addView(q,full(6));LinearLayout results=col();body.addView(results);get("search",path("global-search"),x->{JSONArray all=x.optJSONArray("results");Runnable paint=()->paintSearch(results,all,q.getText().toString());paint.run();q.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){paint.run();}public void afterTextChanged(Editable e){}});});}
 private void paintSearch(LinearLayout box,JSONArray all,String query){box.removeAllViews();String q=query==null?"":query.trim().toLowerCase(Locale.ROOT);int shown=0;if(all!=null)for(int i=0;i<all.length()&&shown<100;i++){JSONObject r=all.optJSONObject(i);if(r==null)continue;String hay=(r.optString("searchText")+" "+r.optString("title")+" "+r.optString("subtitle")).toLowerCase(Locale.ROOT);if(!q.isEmpty()&&!hay.contains(q))continue;shown++;String kind=r.optString("kind");LinearLayout c=col();c.setPadding(dp(14),dp(11),dp(14),dp(11));c.setBackground(shape(SURFACE,12));TextView t=text(r.optString("title"),15,NAVY);t.setTypeface(null,Typeface.BOLD);c.addView(t);c.addView(text(kind.toUpperCase(Locale.ROOT)+" • "+r.optString("subtitle"),12,MUTED));if(r.has("amount"))c.addView(text(amount(r.optDouble("amount")),13,TEAL));String party=r.optString("party",r.optString("ledger"));c.setOnClickListener(v->{if("order".equals(kind))startActivity(new Intent(this,OrdersActivity.class));else if(!party.isEmpty())showCustomer(party);});box.addView(c,full(7));}if(shown==0)box.addView(text(q.isEmpty()?"No synchronized search data yet.":"No match found.",14,MUTED),full(18));}

 private void customerPicker(){frame("Customer 360","Orders • invoices • outstanding • activity • follow-ups");EditText p=new EditText(this);p.setHint("Type exact customer / ledger name");p.setTextColor(NAVY);p.setHintTextColor(MUTED);p.setTextSize(16);p.setSingleLine(true);p.setPadding(dp(14),dp(12),dp(14),dp(12));p.setBackground(shape(SURFACE,12));body.addView(p,full(8));body.addView(primary("Open customer",v->{String n=p.getText().toString().trim();if(n.isEmpty())toast("Enter customer name");else showCustomer(n);}),full(8));body.addView(button("Find customer using Search",v->showSearch()),full(8));}
 private void showCustomer(String party){frame("Customer 360",party+" • "+company);get("customer",path("customer-workspace","party",party,"refresh","0"),x->renderCustomer(party,x));}
 private void renderCustomer(String party,JSONObject x){body.removeAllViews();JSONObject c=x.optJSONObject("customer");if(c==null)c=new JSONObject();card(party,c.optInt("pendingBillCount")+" pending bills",amount(c.optDouble("outstanding")),null);card("Overdue","Saved bill details",amount(c.optDouble("overdue")),null);JSONArray po=x.optJSONArray("pendingOrders");heading("Pending orders",po==null?"0":po.length()+" order(s)");renderOrders(po,false);JSONArray ds=x.optJSONArray("dispatchedOrders");heading("Recently dispatched",ds==null?"0":ds.length()+" order(s)");renderOrders(ds,true);JSONArray fs=x.optJSONArray("followUps");heading("Payment follow-ups",fs==null?"0":fs.length()+" open");if(fs!=null)for(int i=0;i<fs.length();i++){JSONObject f=fs.optJSONObject(i);if(f!=null)followUpCard(f);}body.addView(primary("+ Add follow-up",v->followUpDialog(party,null)),full(12));String last=x.optString("lastPurchaseDate");if(!last.isEmpty())card("Last purchase",last,"",null);JSONArray frequent=x.optJSONArray("frequentItems");heading("Frequently purchased",frequent==null||frequent.length()==0?"Saved invoice details will build this list.":"From saved Sales invoice details");if(frequent!=null)for(int i=0;i<frequent.length();i++){JSONObject f=frequent.optJSONObject(i);if(f!=null)card(f.optString("name"),f.optInt("count")+" saved invoice(s)","",null);}JSONArray invoices=c.optJSONArray("latestInvoices");heading("Latest invoices",invoices==null?"No saved invoices":invoices.length()+" saved");if(invoices!=null)for(int i=0;i<invoices.length();i++){JSONObject a=invoices.optJSONObject(i);if(a!=null)card(a.optString("number"),a.optString("date"),amount(a.optDouble("amount")),null);}}
 private void renderOrders(JSONArray a,boolean dispatched){if(a==null||a.length()==0){body.addView(text("None",13,MUTED));return;}for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null)card(o.optString("number"),o.optString("buyer")+(o.optString("dispatchedThrough").isEmpty()?"":" • "+o.optString("dispatchedThrough")),dispatched?"DISPATCHED":"PENDING",v->startActivity(new Intent(this,OrdersActivity.class)));}}

 private void showFollowUps(){frame("Follow-ups","Payment promises and contact notes");body.addView(primary("+ New follow-up",v->followUpDialog("",null)),full(5));get("follow-ups",path("followups"),this::renderFollowUps);}
 private void renderFollowUps(JSONObject x){JSONArray over=x.optJSONArray("overdue"),due=x.optJSONArray("dueToday"),open=x.optJSONArray("open");heading("Due now",x.optInt("overdueCount")+" overdue • "+x.optInt("dueCount")+" today");Set<String> seen=new HashSet<>();if(over!=null)for(int i=0;i<over.length();i++){JSONObject f=over.optJSONObject(i);if(f!=null&&seen.add(f.optString("id")))followUpCard(f);}if(due!=null)for(int i=0;i<due.length();i++){JSONObject f=due.optJSONObject(i);if(f!=null&&seen.add(f.optString("id")))followUpCard(f);}heading("Open",x.optInt("openCount")+" total");if(open!=null)for(int i=0;i<open.length();i++){JSONObject f=open.optJSONObject(i);if(f!=null&&seen.add(f.optString("id")))followUpCard(f);}}
 private void followUpCard(JSONObject f){LinearLayout c=col();c.setPadding(dp(14),dp(12),dp(14),dp(12));c.setBackground(shape(SURFACE,13));TextView t=text(f.optString("party"),15,NAVY);t.setTypeface(null,Typeface.BOLD);c.addView(t);String detail=(f.optString("promiseDate").isEmpty()?"No promise date":"Promise "+f.optString("promiseDate"))+(f.optString("note").isEmpty()?"":" • "+f.optString("note"));c.addView(text(detail,12,MUTED));if(f.optDouble("amount")>0)c.addView(text(amount(f.optDouble("amount")),14,TEAL));LinearLayout actions=new LinearLayout(this);Button customer=button("Customer",v->showCustomer(f.optString("party")));Button share=button("Share reminder",v->shareReminder(f));Button done=button("Done",v->completeFollowUp(f));actions.addView(customer,new LinearLayout.LayoutParams(0,-2,1));actions.addView(share,new LinearLayout.LayoutParams(0,-2,1));actions.addView(done,new LinearLayout.LayoutParams(0,-2,1));c.addView(actions,full(7));body.addView(c,full(7));}
 private void followUpDialog(String preset,JSONObject original){LinearLayout box=col();box.setPadding(dp(18),dp(4),dp(18),0);EditText party=new EditText(this);party.setHint("Customer / ledger");party.setText(preset);EditText amount=new EditText(this);amount.setHint("Amount (optional)");amount.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);EditText date=new EditText(this);date.setHint("Promise date YYYY-MM-DD");EditText note=new EditText(this);note.setHint("Note / what customer said");for(EditText e:new EditText[]{party,amount,date,note}){e.setTextColor(NAVY);e.setHintTextColor(MUTED);e.setPadding(dp(12),dp(10),dp(12),dp(10));e.setBackground(shape(SURFACE,10));box.addView(e,full(7));}if(original!=null){party.setText(original.optString("party"));if(original.optDouble("amount")>0)amount.setText(String.valueOf(original.optDouble("amount")));date.setText(original.optString("promiseDate"));note.setText(original.optString("note"));}new AlertDialog.Builder(this).setTitle(original==null?"New payment follow-up":"Edit follow-up").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{try{JSONObject q=new JSONObject().put("company",company).put("party",party.getText().toString().trim()).put("amount",amount.getText().toString().trim().isEmpty()?0:Double.parseDouble(amount.getText().toString().trim())).put("promiseDate",date.getText().toString().trim()).put("note",note.getText().toString().trim()).put("status","open");if(original!=null)q.put("id",original.optString("id"));post("/api/v1/mobile/followups",q,this::showFollowUps);}catch(Exception e){toast("Check amount and date");}}).show();}
 private void completeFollowUp(JSONObject f){try{JSONObject q=new JSONObject(f.toString()).put("status","completed");post("/api/v1/mobile/followups",q,this::showFollowUps);}catch(Exception e){toast(e.getMessage());}}
 private void shareReminder(JSONObject f){StringBuilder b=new StringBuilder("Payment follow-up\nCustomer: ").append(f.optString("party"));if(f.optDouble("amount")>0)b.append("\nAmount: ").append(amount(f.optDouble("amount")));if(!f.optString("promiseDate").isEmpty())b.append("\nPromise date: ").append(f.optString("promiseDate"));if(!f.optString("note").isEmpty())b.append("\nNote: ").append(f.optString("note"));try{startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,b.toString()),"Share follow-up"));}catch(Exception e){toast("No sharing app available");}}

 private void showSystem(){frame("System","Health • diagnostics • Tally performance • signing");busy(true);work.execute(()->{try{JSONObject health=api.get(path("health")),diag=api.get(path("diagnostics")),perf=api.get(path("tally-performance"));main.post(()->{if(destroyed)return;busy(false);renderSystem(health,diag,perf);});}catch(Exception e){main.post(()->{if(destroyed)return;busy(false);card("System check failed",e.getMessage(),"",v->showSystem());});}});}
 private void renderSystem(JSONObject h,JSONObject d,JSONObject p){body.removeAllViews();heading("Company Health",h.optInt("score")+"% complete");JSONArray items=h.optJSONArray("items");if(items!=null)for(int i=0;i<items.length();i++){JSONObject x=items.optJSONObject(i);if(x!=null)card((x.optBoolean("ok")?"✓ ":"! ")+x.optString("label"),x.optBoolean("ok")?x.optString("value"):x.optString("hint"),x.optBoolean("ok")?"READY":"FIX",null);}heading("Diagnostics","Android "+version()+" • PC "+d.optString("version"));card("Android signing",AppIdentity.status(this),"",null);card("SHA-1",AppIdentity.sha1(this),"",null);card("SHA-256",AppIdentity.sha256(this),"",null);card("Package",getPackageName(),"",null);card("Google access / phone key",store.get("device").isEmpty()?"Not approved":"Approved phone key present","",null);JSONObject cache=d.optJSONObject("cache");if(cache!=null)card("Saved cache",cache.optInt("entries")+" entries • "+cache.optString("latestAt"),"",null);try{OfflineOrdersStore os=new OfflineOrdersStore(store);int waiting=os.waitingCount(),photos=os.pendingPhotoUploadCount();card("Offline order queue",waiting+" unsynced change(s) • "+photos+" photo(s) waiting",waiting==0&&photos==0?"CLEAR":"WAITING",null);}catch(Exception e){card("Offline order queue","Could not read phone queue","CHECK",null);}card("PC bridge",d.optString("version").isEmpty()?"Unavailable":"Connected • "+d.optString("version"),company,null);if(!version().equals(d.optString("version")))card("Version mismatch","Update Android/Windows so both use the same release.",version()+" / "+d.optString("version"),null);heading("Tally protection",p.optString("gateState")+(p.optLong("cooldownSeconds")>0?" • cooldown "+p.optLong("cooldownSeconds")+"s":""));card("Read success",p.optInt("successReads")+" successful • "+p.optInt("failedReads")+" failed",p.optInt("successRate")+"%",null);card("Response time","P95 "+p.optLong("p95Ms")+" ms • "+p.optInt("slowReads")+" slow reads",p.optLong("averageMs")+" ms avg",null);if(!p.optString("lastError").isEmpty())card("Last Tally error",p.optString("lastError"),"",null);}
 private String version(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception e){return "?";}}
}
